{
  "items": [
    {
      "name": "MvPolynomial.optionEquivLeft",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "definition",
      "type": "(R : Type u) → (S₁ : Type v) → [inst : CommSemiring R] → MvPolynomial (Option S₁) R ≃ₐ[R] Polynomial (MvPolynomial S₁ R)"
    },
    {
      "name": "MvPolynomial.degree_optionEquivLeft",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) {σ : Type u_1} [inst : CommSemiring R] {f : MvPolynomial (Option σ) R},\n  f ≠ 0 → ((MvPolynomial.optionEquivLeft R σ) f).degree = ↑(MvPolynomial.degreeOf none f)"
    },
    {
      "name": "MvPolynomial.totalDegree_coeff_optionEquivLeft_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) (S₁ : Type v) [inst : CommSemiring R] (p : MvPolynomial (Option S₁) R) (i : ℕ),\n  (((MvPolynomial.optionEquivLeft R S₁) p).coeff i).totalDegree ≤ p.totalDegree"
    },
    {
      "name": "MvPolynomial.natDegree_optionEquivLeft",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial (Option σ) R),\n  ((MvPolynomial.optionEquivLeft R σ) p).natDegree = MvPolynomial.degreeOf none p"
    },
    {
      "name": "MvPolynomial.optionEquivLeft_coeff_coeff",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ (R : Type u) {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial (Option σ) R) (m : ℕ) (d : σ →₀ ℕ),\n  MvPolynomial.coeff d (((MvPolynomial.optionEquivLeft R σ) p).coeff m) = MvPolynomial.coeff (Finsupp.optionElim m d) p"
    }
  ]
}
